/* Cooking video for the product page ("Real Preparation Video" card): starts muted when it scrolls into view, tap for sound.
 *
 * Data:  window.PRODUCT_VIDEOS (videos/product-videos.js, generated by tools/upload-cooking-videos.py): product id -> { poster, duration, w, h, sources:[{u,w,h}] }
 *        The videos are hosted by Shopify (cdn.shopify.com). Nothing about them is in the repo except the small poster images.
 * Use:   main.js puts MMVideo.cardHtml(product) in the card (a poster button, no <video>, so no video request), calls MMVideo.observe(container) after the
 *        product page is drawn, and its click listener calls MMVideo.play(button) / MMVideo.sound(button).
 *        - When the card is at least half on screen the <video> is created and plays muted and looping (720p). It pauses when the card scrolls away
 *          and resumes when it comes back. "Tap for sound" restarts it from the beginning with sound and without looping.
 *        - No autoplay (the poster stays, tap to play) when the visitor asked for reduced motion or Save-Data, or is on a 2G connection,
 *          or if the browser refuses autoplay.
 *        - Leaving the page removes the card (the view is re-rendered); the observer is disconnected and anything still playing is paused.
 */
(function () {
  'use strict';

  var io = null;

  function esc(s) { return String(s).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;'); }
  function mmss(sec) { sec = Math.max(0, Math.round(sec || 0)); return Math.floor(sec / 60) + ':' + String(sec % 60).padStart(2, '0'); }

  function entryFor(id) {
    var all = window.PRODUCT_VIDEOS;
    var e = all && all[id];
    return e && e.sources && e.sources.length ? e : null;
  }

  // '' when this product has no video of its own (main.js then keeps the generic video)
  function cardHtml(p) {
    var e = entryFor(p.id);
    if (!e) return '';
    var label = 'Play video: how to prepare ' + esc(p.title);
    return '<button type="button" class="mmv-play" data-mmv="' + esc(p.id) + '" aria-label="' + label + '">' +
      '<img class="mmv-poster" src="' + esc(e.poster) + '" alt="" width="' + (e.w || 478) + '" height="' + (e.h || 850) + '" loading="lazy" decoding="async">' +
      '<span class="mmv-icon" aria-hidden="true"><svg width="26" height="26" viewBox="0 0 24 24" fill="currentColor"><polygon points="7 4 20 12 7 20 7 4"/></svg></span>' +
      '<span class="mmv-dur" aria-hidden="true">' + mmss(e.duration) + '</span>' +
      '</button>';
  }

  // smallest rendition that is at least `want` pixels tall (else the biggest)
  function pick(e, want) {
    var list = e.sources.slice().sort(function (a, b) { return a.h - b.h; });
    for (var i = 0; i < list.length; i++) if (list[i].h >= want) return list[i];
    return list[list.length - 1];
  }
  function manualHeight() { return 720; }

  function autoplayAllowed() {
    if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return false;
    var c = navigator.connection;
    if (c && (c.saveData || /(^|-)2g$/.test(c.effectiveType || ''))) return false;
    return 'IntersectionObserver' in window;
  }

  function clearBits(card) {
    var m = card.querySelector('.mmv-msg'); if (m) m.parentNode.removeChild(m);
    var s = card.querySelector('.mmv-sound'); if (s) s.parentNode.removeChild(s);
  }

  // back to the poster; a message only when the visitor asked for the video themselves
  function fail(card, btn, video, silent) {
    if (video && video.parentNode) video.parentNode.removeChild(video);
    clearBits(card);
    btn.hidden = false;
    if (silent) return;
    var m = document.createElement('p');
    m.className = 'mmv-msg';
    m.setAttribute('role', 'alert');
    m.textContent = 'The video could not load. Tap to try again.';
    card.appendChild(m);
    btn.focus();
  }

  function makeVideo(card, btn, e, height, auto) {
    clearBits(card);
    var v = document.createElement('video');
    v.className = 'pdp-hiw-video mmv-video';
    v.controls = true;
    v.playsInline = true;
    v.preload = 'auto';
    v.poster = e.poster;
    if (auto) { v.muted = true; v.setAttribute('muted', ''); v.loop = true; }
    v.setAttribute('aria-label', (btn.getAttribute('aria-label') || '').replace(/^Play video: /, 'Video: '));
    v.addEventListener('error', function () { fail(card, btn, v, auto); }, { once: true });
    v.src = pick(e, height).u;
    card.insertBefore(v, btn);
    btn.hidden = true;
    return v;
  }

  function startAuto(card) {
    var btn = card.querySelector('.mmv-play');
    var e = btn && entryFor(btn.dataset.mmv);
    if (!e || card.querySelector('video.mmv-video')) return;
    var v = makeVideo(card, btn, e, 720, true);   // 720p: sharper than 480p on retina screens (the originals are only 478 px wide, so more would not help)
    var s = document.createElement('button');
    s.type = 'button';
    s.className = 'mmv-sound';
    s.setAttribute('data-mmv-sound', '');
    s.setAttribute('aria-label', 'Turn sound on and play from the start');
    s.innerHTML = '<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5" fill="currentColor"/><path d="M15.5 8.5a5 5 0 0 1 0 7M19 5a10 10 0 0 1 0 14"/></svg><span>Tap for sound</span>';
    card.appendChild(s);
    v.addEventListener('volumechange', function () { if (!v.muted && s.parentNode) s.parentNode.removeChild(s); });
    var p = v.play();
    if (p && p.catch) p.catch(function () { fail(card, btn, v, true); });   // the browser refused autoplay: keep the poster, tap to play
  }

  function onIntersect(entries) {
    entries.forEach(function (en) {
      var card = en.target;
      var v = card.querySelector('video.mmv-video');
      if (en.intersectionRatio >= 0.5) {
        if (!v) startAuto(card);
        else if (v._mmvAutoPaused && v.paused) { v._mmvAutoPaused = false; var p = v.play(); if (p && p.catch) p.catch(function () { /* controls are showing */ }); }
      } else if (en.intersectionRatio < 0.25 && v && !v.paused) {
        v._mmvAutoPaused = !v.muted ? false : true;   // resume by itself only while it is still the silent preview
        v.pause();
      }
    });
  }

  function disconnect() { if (io) { io.disconnect(); io = null; } }

  // call after the product page has been drawn
  function observe(root) {
    disconnect();
    if (!autoplayAllowed()) return;
    var cards = [];
    (root || document).querySelectorAll('.mmv-play').forEach(function (b) { if (b.parentNode) cards.push(b.parentNode); });
    if (!cards.length) return;
    io = new IntersectionObserver(onIntersect, { threshold: [0, 0.25, 0.5] });
    cards.forEach(function (c) { io.observe(c); });
  }

  // the visitor tapped the poster (autoplay off or refused): play with sound
  function play(btn) {
    var e = entryFor(btn.dataset.mmv);
    var card = btn.parentNode;
    if (!e || !card) return;
    var v = makeVideo(card, btn, e, manualHeight(), false);
    var p = v.play();
    if (p && p.catch) p.catch(function (err) {
      if (err && (err.name === 'NotAllowedError' || err.name === 'AbortError')) return;   // controls are showing / removed meanwhile
      fail(card, btn, v, false);
    });
    try { v.focus({ preventScroll: true }); } catch (_) { /* ignore */ }
  }

  // "Tap for sound": from the start, with sound, no loop
  function sound(btn) {
    var card = btn.parentNode;
    var v = card && card.querySelector('video.mmv-video');
    if (!v) return;
    v.loop = false;
    v.muted = false;
    v.currentTime = 0;
    var p = v.play();
    if (p && p.catch) p.catch(function () { /* controls are showing */ });
    if (btn.parentNode) btn.parentNode.removeChild(btn);
    try { v.focus({ preventScroll: true }); } catch (_) { /* ignore */ }
  }

  function stop() {
    disconnect();
    document.querySelectorAll('video.mmv-video').forEach(function (v) { try { v.pause(); } catch (_) { /* ignore */ } });
  }
  window.addEventListener('hashchange', stop);
  document.addEventListener('visibilitychange', function () {
    if (document.hidden) document.querySelectorAll('video.mmv-video').forEach(function (v) { if (!v.paused && v.muted) { v._mmvAutoPaused = true; v.pause(); } });
    else document.querySelectorAll('video.mmv-video').forEach(function (v) { if (v._mmvAutoPaused && v.paused) { var r = v.getBoundingClientRect(); if (r.bottom > 0 && r.top < window.innerHeight) { v._mmvAutoPaused = false; var p = v.play(); if (p && p.catch) p.catch(function () {}); } } });
  });

  window.MMVideo = { cardHtml: cardHtml, observe: observe, play: play, sound: sound, stop: stop };
})();
